package dev.arabicgames.phone;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Only explicit reviewed, exact, game-scoped pairs. Reports never feed inference automatically. */
final class CommunityCorrections {
 private static volatile java.util.List<ReviewedLanguage.Rule> rules=java.util.Collections.emptyList();
 private static volatile Map<String,String> pairs=Collections.emptyMap();private static volatile boolean initialized,refreshing;private static volatile int revision;static volatile String syncStatus="التصحيحات المراجعة المضمنة جاهزة.";
 static String key(String game,String source){return GameNames.key(game)+"\n"+source.replace('\u2019','\'').replaceAll("\\s+"," ").trim().toLowerCase(Locale.ROOT);}
 static Map<String,String> parse(String text)throws Exception {JSONObject root=new JSONObject(text);if(!root.getString("format").equals("arabic-games-reviewed-v1")||!root.getString("source").equals("en")||!root.getString("target").equals("ar"))throw new IOException("Invalid correction format");JSONArray rows=root.getJSONArray("entries");if(rows.length()>10000)throw new IOException("Too many corrections");Map<String,String> loaded=new HashMap<>();for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);if(!e.getBoolean("reviewed"))throw new IOException("Unreviewed line");String game=e.getString("game"),source=e.getString("source"),arabic=e.getString("arabic");if(game.isBlank()||game.length()>200||source.isBlank()||source.length()>2000||arabic.isBlank()||arabic.length()>3000)throw new IOException("Invalid correction");String key=key(game,source);if(loaded.containsKey(key)&&!loaded.get(key).equals(arabic))throw new IOException("Conflicting correction");loaded.put(key,arabic);}ReviewedLanguage.parse(text);return Collections.unmodifiableMap(loaded);}
 private static String read(InputStream in)throws Exception {try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>1_000_000)throw new IOException("Correction pack too large");out.write(b,0,n);}return out.toString("UTF-8");}}
 static synchronized void initialize(Context c){if(initialized)return;try{String bundled=read(c.getAssets().open("reviewed-dialogue.json"));pairs=parse(bundled);rules=ReviewedLanguage.parse(bundled);revision=new JSONObject(bundled).optInt("revision",0);File cache=new File(c.getFilesDir(),"community-reviewed.json");if(cache.isFile())try{String stored=read(new FileInputStream(cache));int cachedRevision=new JSONObject(stored).optInt("revision",0);if(cachedRevision>=revision){pairs=parse(stored);rules=ReviewedLanguage.parse(stored);revision=cachedRevision;}}catch(Exception ignored){}}catch(Exception ignored){}initialized=true;}

 static String hints(String game,String source){return ReviewedLanguage.hints(rules,game,source);}
 static String improve(Context c,String game,String source,String arabic){initialize(c);return ReviewedLanguage.apply(rules,game,source,arabic);}
 static String find(Context c,String game,String source){initialize(c);return pairs.get(key(game,source));}
 static void refresh(Context context){refresh(context,false,null);}
 static synchronized void refresh(Context context,boolean force,Runnable done){Context c=context.getApplicationContext();initialize(c);if(refreshing)return;if(!force&&(!c.getSharedPreferences("reading",0).getBoolean("communityUpdates",true)||System.currentTimeMillis()-c.getSharedPreferences("reading",0).getLong("communityChecked",0)<12*60*60*1000L))return;refreshing=true;syncStatus="جارٍ تنزيل التصحيحات المراجعة فقط…";
  Thread thread=new Thread(()->{HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL("https://raw.githubusercontent.com/Tariq-220/ArabicGamesTranslator/main/community/reviewed-dialogue.json").openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(15000);if(connection.getResponseCode()!=200)throw new IOException("HTTP");String text=read(connection.getInputStream());Map<String,String> loaded=parse(text);int downloadedRevision=new JSONObject(text).optInt("revision",0);if(downloadedRevision<revision)throw new IOException("Older pack");File tmp=new File(c.getFilesDir(),"community-reviewed.tmp"),target=new File(c.getFilesDir(),"community-reviewed.json");Files.write(tmp.toPath(),text.getBytes(StandardCharsets.UTF_8));Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);pairs=loaded;rules=ReviewedLanguage.parse(text);revision=downloadedRevision;syncStatus="تم تحديث التصحيحات: "+loaded.size()+" مدخلًا مراجعًا. ستستخدم تلقائيًا للجملة واللعبة نفسيهما.";CaptionNoise.invalidate();c.getSharedPreferences("reading",0).edit().putLong("communityChecked",System.currentTimeMillis()).apply();}catch(Exception ignored){syncStatus="تعذر تحديث التصحيحات؛ الحزمة السابقة محفوظة. أعد المحاولة لاحقًا.";}finally{if(connection!=null)connection.disconnect();refreshing=false;if(done!=null)new android.os.Handler(android.os.Looper.getMainLooper()).post(done);}},"reviewed-corrections");thread.setDaemon(true);thread.start();
 }
}
